<script setup>
import { onMounted, reactive, ref } from 'vue';
import { GripVertical } from 'lucide-vue-next';
import { api } from '../../lib/api.js';
import { appUrl } from '../../lib/navigation.js';
import { reorderDirective } from '../../directives/reorder.js';
import ThemeSelect from '../common/ThemeSelect.vue';
const state = ref(null), busy = ref(false), error = ref(''), notice = ref(''), dialog = ref(null), target = ref(null);
const draft = reactive({});
const providers = [{ value: 'prometheus', label: 'Prometheus · PromQL' }, { value: 'grafana', label: 'Grafana · Prometheus 데이터 소스' }, { value: 'kuma', label: 'Uptime Kuma · 상태 페이지' }];
const labels = { fastlink: '빠른 링크', tabs: '탭 선택', weather: '날씨', clock: '시계 · 달력', theme: '테마 전환', settings: '설정', logout: '로그아웃', edit: '화면 순서 편집 버튼' };
const label = key => labels[key] || state.value.metrics.find(item => 'metric:' + item.id === key)?.name || '모니터링';
const required = key => ['settings', 'logout'].includes(key);
async function load() { state.value = await api('admin/footer'); }
onMounted(async () => { try { await load(); } catch (cause) { error.value = cause.message; } });
function reorder(kind, parentId, ids) { state.value.order = ids; }
const vReorder = reorderDirective(reorder);
function move(key, delta) { const ids = [...state.value.order], index = ids.indexOf(key), next = index + delta; if (next < 0 || next >= ids.length) return; [ids[index], ids[next]] = [ids[next], ids[index]]; state.value.order = ids; }
function toggle(key, checked) { state.value.hidden = checked ? state.value.hidden.filter(item => item !== key) : [...state.value.hidden, key]; }
async function saveLayout() { busy.value = true; error.value = ''; try { await api('admin/footer', { method: 'PUT', body: JSON.stringify({ order: state.value.order, hidden: state.value.hidden }) }); notice.value = '하단바 구성을 저장했어요. 메인 화면을 새로 열면 적용됩니다.'; } catch (cause) { error.value = cause.message; } finally { busy.value = false; } }
function edit(item = null) { target.value = item; error.value = ''; Object.assign(draft, { name: item?.name || '', provider: item?.provider || 'prometheus', base_url: item?.base_url || 'https://', token: '', clear_token: false, query: item?.query || '', datasource_uid: item?.datasource_uid || '', slug: item?.slug || 'default', monitor_id: item?.monitor_id || '', metric: item?.metric || 'status', display: item?.display || 'sparkline', unit: item?.unit || '', interval: item?.interval || 60, window: item?.window || 3600, allow_private: item?.allow_private || false, enabled: item?.enabled ?? true, audience: item?.audience || 'admin' }); dialog.value.showModal(); }
function providerChanged() { if (draft.provider !== 'kuma' && draft.display === 'status') draft.display = 'sparkline'; if (draft.provider === 'kuma') { draft.display = 'status'; draft.metric = 'status'; draft.unit = ''; } }
async function saveMetric() { busy.value = true; error.value = ''; try { await api('admin/footer/metrics' + (target.value ? '/' + target.value.id : ''), { method: target.value ? 'PUT' : 'POST', body: JSON.stringify({ ...draft, token: draft.token || null, interval: Number(draft.interval), window: Number(draft.window) }) }); dialog.value.close(); await load(); notice.value = '모니터링 위젯을 저장했어요. ‘지금 확인’으로 연결을 확인하세요.'; } catch (cause) { error.value = cause.message; } finally { busy.value = false; } }
async function check(item) { busy.value = true; error.value = ''; try { await api('admin/footer/metrics/' + item.id + '/check', { method: 'POST' }); await load(); } catch (cause) { error.value = cause.message; } finally { busy.value = false; } }
async function remove(item) { if (!confirm(`‘${item.name}’ 위젯을 삭제할까요?`)) return; try { await api('admin/footer/metrics/' + item.id, { method: 'DELETE' }); await load(); } catch (cause) { error.value = cause.message; } }
</script>
<template><section class="settings-section"><p v-if="error && !dialog?.open" class="form-error" role="alert">{{ error }}</p><p v-if="notice" class="form-notice" role="status">{{ notice }}</p>
<div v-if="state" class="settings-card" data-settings-anchor="footer-layout"><div class="card-heading"><h2>하단바 구성</h2><a class="secondary-button" :href="appUrl('?edit=1')">메인에서 순서 편집</a></div><p class="settings-description">손잡이를 드래그하여 기본 순서를 변경하고, 표시할 항목을 선택하세요. 설정·로그아웃은 항상 표시됩니다. 화면 순서 편집 버튼도 위치와 표시 여부를 변경할 수 있습니다. 사용자가 메인 화면에서 바꾼 개인 순서는 우선 적용되며 ‘하단바 기본 순서 복원’으로 되돌릴 수 있습니다.</p><div v-reorder="{ kind: 'footer', disabled: busy }"><article v-for="key in state.order" :key="key" :data-sort-id="key" class="editable-link"><button class="reorder-handle icon-button" :aria-label="label(key) + ' 기본 순서 변경 · 위아래 방향키'" @keydown.up.prevent="move(key, -1)" @keydown.down.prevent="move(key, 1)"><GripVertical :size="16" /></button><strong class="operation-row-content">{{ label(key) }}</strong><label class="checkbox-label"><input type="checkbox" :checked="!state.hidden.includes(key)" :disabled="required(key)" @change="toggle(key, $event.target.checked)" />{{ required(key) ? '필수 표시' : '표시' }}</label></article></div><button class="primary-button" :disabled="busy" @click="saveLayout">하단바 구성 저장</button></div>
<div v-if="state" class="settings-card" data-settings-anchor="footer-widgets"><div class="card-heading"><h2>외부 모니터링 위젯</h2><button class="primary-button" @click="edit()">모니터링 위젯 추가</button></div><p class="settings-description">CPU·메모리 등은 Prometheus에서 하나의 시계열을 반환하는 PromQL로 조회하세요. Grafana는 Prometheus 데이터 소스 UID와 조회 권한이 있는 서비스 계정 토큰을 사용합니다. Uptime Kuma는 게시된 상태 페이지의 모니터를 조회합니다. API 토큰은 서버에 암호화하여 보관합니다.</p><p class="settings-description">‘모든 사용자’로 설정한 위젯의 측정값은 로그인한 모든 사용자에게 표시됩니다. API 주소·쿼리·토큰은 일반 사용자에게 전달하지 않습니다.</p><article v-for="item in state.metrics" :key="item.id" class="editable-link"><div class="operation-row-content"><strong>{{ item.name }}</strong><small>{{ item.provider }} · {{ item.audience === 'all' ? '모든 사용자' : '관리자만' }} · {{ item.enabled ? item.result?.available ? '수신 정상' : item.result?.detail || '수신 대기' : '중지됨' }}</small></div><div class="inline-actions"><button class="secondary-button" :disabled="busy" :aria-label="item.name + ' 위젯 지금 확인'" @click="check(item)">지금 확인</button><button class="secondary-button" :aria-label="item.name + ' 위젯 수정'" @click="edit(item)">수정</button><button class="secondary-button danger" :aria-label="item.name + ' 위젯 삭제'" @click="remove(item)">삭제</button></div></article><p v-if="!state.metrics.length" class="settings-empty">등록한 모니터링 위젯이 없습니다.</p></div>
<dialog ref="dialog" v-dialog-dismiss="busy" @close="draft.token = ''" class="editor-dialog"><form class="settings-form" @submit.prevent="saveMetric"><div class="card-heading"><h2>모니터링 위젯 설정</h2><button type="button" class="icon-button" aria-label="닫기" :disabled="busy" @click="dialog.close()">×</button></div><label>위젯 이름<input v-model="draft.name" required maxlength="60" placeholder="CPU" /></label><label>모니터링 서비스<ThemeSelect v-model="draft.provider" label="모니터링 서비스" :options="providers" @change="providerChanged" /></label><label>서비스 기본 주소<input v-model="draft.base_url" type="url" required maxlength="2048" placeholder="https://prometheus.example.com" /><small>서브 경로도 사용할 수 있습니다. 주소를 변경하면 기존 토큰을 제거합니다.</small></label><label>API Bearer 토큰 (선택)<input v-model="draft.token" type="password" maxlength="4096" autocomplete="new-password" :placeholder="target?.has_token ? '저장됨 · 비우면 유지' : '조회 권한이 있는 토큰'" /></label><label v-if="target?.has_token" class="checkbox-label"><input v-model="draft.clear_token" type="checkbox" />저장한 토큰 제거</label>
<template v-if="draft.provider !== 'kuma'"><label v-if="draft.provider === 'grafana'">Prometheus 데이터 소스 UID<input v-model="draft.datasource_uid" required maxlength="128" /></label><label>PromQL<input v-model="draft.query" required maxlength="2048" placeholder='100 * (1 - avg(rate(node_cpu_seconds_total{mode="idle"}[5m])))' /><small>결과가 하나의 시계열이어야 합니다. 예: 100 * (1 - node_memory_MemAvailable_bytes / node_memory_MemTotal_bytes)</small></label><label>그래프 조회 범위<ThemeSelect v-model="draft.window" label="그래프 조회 범위" :options="[{ value: 900, label: '최근 15분' }, { value: 3600, label: '최근 1시간' }, { value: 21600, label: '최근 6시간' }, { value: 86400, label: '최근 24시간' }]" /></label></template>
<template v-else><label>상태 페이지 Slug<input v-model="draft.slug" required maxlength="128" placeholder="default" /><small>예: /status/home이면 home. 게시된 상태 페이지가 필요합니다.</small></label><label>모니터 ID<input v-model="draft.monitor_id" required inputmode="numeric" pattern="[0-9]+" maxlength="20" /></label><label>측정 정보<ThemeSelect v-model="draft.metric" label="측정 정보" :options="[{ value: 'status', label: '서비스 상태' }, { value: 'latency', label: '응답 시간 (ms)' }, { value: 'uptime', label: '24시간 가동률 (%)' }]" @change="draft.display = draft.metric === 'status' ? 'status' : draft.metric === 'latency' ? 'sparkline' : 'value'; draft.unit = draft.metric === 'latency' ? 'ms' : draft.metric === 'uptime' ? '%' : ''" /></label></template>
<label>표시 방식<ThemeSelect v-model="draft.display" label="표시 방식" :options="[{ value: 'value', label: '숫자' }, { value: 'sparkline', label: '작은 그래프 + 숫자' }, ...(draft.provider === 'kuma' && draft.metric === 'status' ? [{ value: 'status', label: '상태 도트 + 상태 이름' }] : [])]" /></label><label>표시 단위 (선택)<input v-model="draft.unit" maxlength="12" placeholder="%, ms, GB" /><small>단위는 표시용입니다. PromQL 결과의 단위를 맞춰 주세요.</small></label><label>조회 간격 (초)<input v-model="draft.interval" type="number" min="60" max="86400" required /></label><label>위젯 공개 대상<ThemeSelect v-model="draft.audience" label="위젯 공개 대상" :options="[{ value: 'admin', label: '관리자만' }, { value: 'all', label: '모든 사용자' }]" /></label><label class="checkbox-label"><input v-model="draft.allow_private" type="checkbox" />내부 네트워크 주소 조회 허용</label><label class="checkbox-label"><input v-model="draft.enabled" type="checkbox" />주기적 조회 사용</label><p v-if="error" class="form-error" role="alert">{{ error }}</p><button class="primary-button" :disabled="busy">모니터링 위젯 저장</button></form></dialog>
</section></template>
